// Parse GDACS RSS and keep only Orange/Red alerts within 300 km of Lahore.
const input = $input.first().json;
const raw = typeof input.data === 'string' ? input.data : JSON.stringify(input);

const FARM = { lat: 31.5204, lng: 74.3587, radiusKm: 300 };
const TYPE_LABEL = { EQ: 'earthquake', FL: 'flood', TC: 'cyclone', WF: 'wildfire', VO: 'volcano', DR: 'drought', TS: 'tsunami' };

const getTag = (block, name) => {
  const re = new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${name}>`, 'i');
  const m = block.match(re);
  return m ? m[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').trim() : '';
};

const toRad = (d) => (d * Math.PI) / 180;
const distanceKm = (lat1, lng1, lat2, lng2) => {
  const R = 6371;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
};

const items = [...raw.matchAll(/<item>([\s\S]*?)<\/item>/gi)].map((m) => m[1]);
const staticData = $getWorkflowStaticData('global');
const seen = new Set(staticData.seenAlertIds || []);
const alerts = [];

for (const item of items) {
  const level = getTag(item, 'gdacs:alertlevel');
  if (!/orange|red/i.test(level)) continue;

  let lat = Number(getTag(item, 'geo:lat'));
  let lng = Number(getTag(item, 'geo:long'));
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
    const point = getTag(item, 'georss:point').split(/\s+/).map(Number);
    [lat, lng] = point;
  }
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) continue;

  const dist = distanceKm(FARM.lat, FARM.lng, lat, lng);
  if (dist > FARM.radiusKm) continue;

  const id = `${getTag(item, 'gdacs:eventid')}-${getTag(item, 'gdacs:episodeid')}`;
  if (!id || id === '-' || seen.has(id)) continue;
  seen.add(id);

  alerts.push({
    json: {
      id,
      type: TYPE_LABEL[getTag(item, 'gdacs:eventtype')] || 'disaster',
      title: getTag(item, 'title') || 'Disaster alert',
      severity: level.toLowerCase(),
      country: getTag(item, 'gdacs:country'),
      lat, lng,
      distanceKm: Math.round(dist),
      source: 'GDACS',
      url: getTag(item, 'link') || 'https://www.gdacs.org',
      detectedAt: new Date().toISOString(),
    },
  });
}

staticData.seenAlertIds = [...seen].slice(-500);
return alerts;

return [{
  json: {
    id: 'TEST-' + Date.now().toString(36).toUpperCase(),
    type: 'flood',
    title: 'TEST ALERT — Flood warning near Lahore',
    severity: 'red',
    country: 'Pakistan',
    lat: 31.5204,
    lng: 74.3587,
    distanceKm: 0,
    source: 'Hackathon test trigger',
    url: 'https://www.gdacs.org',
    detectedAt: new Date().toISOString(),
    test: true,
  },
}];
